using EarthUnscripted.TerrainDraft;using System;using System.Linq;using System.Collections.Generic;
namespace EarthUnscripted.TerrainDraft.Core800 {
 public sealed class RoadCellFoundation {
  public readonly LocalTerrainMesh[] Meshes;public readonly Dictionary<string,string[]> Members;public readonly IReadOnlyList<TerrainPoint>[] Contours;public readonly TerrainPoint[] BoundaryPoints;public readonly RoadTerrainSource Geometry;
  internal RoadCellFoundation(LocalTerrainMesh[] meshes,Dictionary<string,string[]> members,TerrainDem dem){Meshes=meshes;Members=members;var points=new List<TerrainPoint>();var ids=new Dictionary<(double,double,double),int>();var edges=new Dictionary<TerrainMeshEdge,List<(int A,int B)>>();int V(TerrainPoint p){var key=(p.X,p.Y,p.Z);if(ids.TryGetValue(key,out int n))return n;n=points.Count;points.Add(p);ids.Add(key,n);return n;}foreach(var p in meshes){var remap=Enumerable.Range(0,p.XYZ.Length/3).Select(i=>V(new TerrainPoint(p.OriginX+p.XYZ[i*3],p.OriginY+p.XYZ[i*3+1],p.OriginZ+p.XYZ[i*3+2]))).ToArray();for(int i=0;i<p.Indices.Length;i+=3){int a=remap[p.Indices[i]],b=remap[p.Indices[i+1]],c=remap[p.Indices[i+2]];foreach(var e in new[]{(a,b),(b,c),(c,a)}){var key=new TerrainMeshEdge(e.Item1,e.Item2);if(!edges.TryGetValue(key,out var list))edges[key]=list=new List<(int,int)>();list.Add(e);if(list.Count>2)throw new ArgumentException("Roadfoundation sourceownership is nonmanifold");}}}
   var next=new Dictionary<int,int>();foreach(var pair in edges.Where(p=>p.Value.Count==1)){var e=pair.Value[0];if(next.ContainsKey(e.A))throw new ArgumentException("Roadfoundation boundarybranches beforeterrain");next[e.A]=e.B;}var loops=new List<IReadOnlyList<TerrainPoint>>();var pending=new HashSet<int>(next.Keys);while(pending.Count>0){int first=pending.Min(),at=first;var loop=new List<TerrainPoint>();do{if(!pending.Remove(at)||!next.TryGetValue(at,out int end))throw new ArgumentException("Roadfoundation boundaryisopen/selftouch");loop.Add(points[at]);at=end;}while(at!=first);loop.Reverse();loops.Add(loop.ToArray());}Contours=loops.ToArray();BoundaryPoints=Contours.SelectMany(p=>p).ToArray();if(meshes.Length>0)Geometry=new RoadTerrainSource(meshes.Select(p=>new RoadTerrainSourcePacket(p.Id,members[p.Id],RoadTerrainSurfaceClass.Ground,p.OriginX,p.OriginY,p.OriginZ,p.XYZ,p.Indices,Array.Empty<double>())).ToArray(),dem);}
  public double BoundaryHeight(double x,double z){double best=double.PositiveInfinity,value=0;foreach(var loop in Contours)for(int i=0;i<loop.Count;i++){var a=loop[i];var b=loop[(i+1)%loop.Count];double dx=b.X-a.X,dz=b.Z-a.Z,len=dx*dx+dz*dz,t=len==0?0:Math.Max(0,Math.Min(1,((x-a.X)*dx+(z-a.Z)*dz)/len)),distance=Math.Sqrt(Math.Pow(a.X+t*dx-x,2)+Math.Pow(a.Z+t*dz-z,2));if(distance<best){best=distance;value=a.Y+t*(b.Y-a.Y);}}if(best>.00002)throw new ArgumentException("Finalsourceboundary lacks canonical foundationedge");return value;}
 }
}
